INSERT INTO notas (id, titulo, dominio_slug, aplicacao_slug, tipo_nota_slug, camadas, sinais, confianca, status, corpo) VALUES (
  $m2936$nota-0165$m2936$, $m2937$VO2máx aumenta via adaptações centrais (débito cardíaco) e periféricas (mitocôndrias/capilarização); ganhos diminuem com o nível do atleta (>20% em iniciantes vs. 2-3% em elite)$m2937$, $m2938$fisiologia$m2938$,
  $m2939$contexto$m2939$, $m2940$conceito$m2940$,
  ARRAY[$m2941$mensal$m2941$]::text[], '{}'::text[],
  0.55, $m2942$ativo$m2942$, $m2943$O VO2máx é elevado por treinamento através de adaptações centrais (aumento de volume sistólico, débito cardíaco, volume plasmático — estimuladas principalmente por intervalados de alta intensidade) e periféricas (densidade mitocondrial, atividade enzimática oxidativa, capilarização — estimuladas por volume aeróbio consistente ao longo de anos). O potencial de ganho não é indefinido: iniciantes podem ganhar >20% de VO2máx; atletas de elite tipicamente apenas 2-3%. Consequência prática: em atletas avançados, o foco de treinamento tende a se deslocar do aumento do VO2máx (teto próximo do limite genético/adaptativo) para melhoria de economia de movimento, limiares fisiológicos e durabilidade.

Aplicação ao feedback: reforça a lógica de que o nível/histórico de treinamento do atleta (contexto-atleta) deveria influenciar a priorização de foco no feedback — para atletas iniciantes/intermediários, estímulos de VO2max (intervalados de alta intensidade) tendem a produzir ganhos mais expressivos; para atletas muito treinados, o produto deveria dar mais peso a sinais relacionados a economia/eficiência e resistência à fadiga em vez de insistir unicamente em mais intervalados de VO2max.$m2943$
)
