INSERT INTO notas (id, titulo, dominio_slug, aplicacao_slug, tipo_nota_slug, camadas, sinais, confianca, status, corpo) VALUES (
  $m2952$nota-0205$m2952$, $m2953$VO2máx como preditor de mortalidade/doença cardiovascular — associação mais forte que fatores de risco tradicionais (colesterol, IMC, glicemia); citação de estudo único (Laukkanen 2022)$m2953$, $m2954$fisiologia$m2954$,
  $m2955$contexto$m2955$, $m2956$conceito$m2956$,
  ARRAY[$m2957$mensal$m2957$]::text[], '{}'::text[],
  0.55, $m2958$ativo$m2958$, $m2959$**Política de ativação aplicada:** a afirmação central (aumentar VO2máx em 3,5 mL/kg/min reduz mortalidade por todas as causas em 11%; top 1/3 de aptidão aeróbia tem 45% menos risco que o 1/3 inferior) é atribuída a um único estudo epidemiológico citado (Laukkanen et al. 2022, Mayo Clinic Proceedings) — downgrade para `aplicacao: contexto` por depender de estudo isolado, sem replicação cruzada dentro do próprio livro. VO2máx é descrito como medida de função integrada do corpo todo (sistema nervoso autônomo, coração/vasos, pulmões, músculos, mitocôndrias), com associação a mortalidade mais forte que fatores de risco cardiovascular tradicionais (colesterol, IMC, glicemia) segundo a fonte.

Aplicação ao feedback: fora do escopo de interpretação de dados de treino do Strava — é conteúdo de motivação/saúde de longo prazo (longevidade), não uma regra de interpretação de sessão. Poderia servir como texto educativo de fundo caso o produto queira comunicar "por que treinar aptidão aeróbia importa", mas não deve ser citado como se fosse consenso robusto (é um único estudo) nem usado para gerar previsões individuais de risco de mortalidade.$m2959$
)
